1	package app
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"sort"
9		"strconv"
10		"strings"
11		"testing"
12	
13		tea "github.com/charmbracelet/bubbletea"
14	
15		"github.com/charmbracelet/x/ansi"
16	
17		"github.com/anthnel/devdesk/internal/command"
18		"github.com/anthnel/devdesk/internal/jobs"
19		"github.com/anthnel/devdesk/internal/ports"
20		"github.com/anthnel/devdesk/internal/template"
21		"github.com/anthnel/devdesk/internal/ui/components"
22		"github.com/anthnel/devdesk/internal/ui/datatable"
23		"github.com/anthnel/devdesk/internal/ui/help"
24		"github.com/anthnel/devdesk/internal/ui/indicator"
25		"github.com/anthnel/devdesk/internal/ui/keymap"
26		"github.com/anthnel/devdesk/internal/ui/netdiag"
27		"github.com/anthnel/devdesk/internal/ui/testutil"
28	)
29	
30	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
31	// (DEVDESK-142).
32	//
33	// The guard answers one question for every view the router can build: is it on
34	// the activity column, is it waiting for its migration, or is it exempt for a
35	// stated reason? A view that is none of the three fails the test by name. For a
36	// migrated view it also checks the column, the help legend, the retired
37	// mechanisms in its declared sources (including its own ticks), and the footer
38	// of its selected row. Declared exceptions may only shrink, and follow their
39	// stories: pendingTables here, declaredRowChains in animation_guard_test.go.
40	
41	// activityView is what a migrated view exposes to the guard: read-only tables,
42	// keyed "<view>/<table>".
43	type activityView interface {
44		ActivityTables() map[string]datatable.ActivityTable
45	}
46	
47	// migratedTables are the tables already on the activity column, by view.
48	var migratedTables = map[command.ViewType][]string{
49		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
50		command.ViewWorkspaces:   {"ws"},
51		command.ViewSecurity:     {"sec/inventory"},
52		command.ViewOCIResources: {"oci/images", "oci/networks", "oci/volumes", "oci/registries"},
53		command.ViewGitExplorer:  {"explorer/tree", "explorer/clone-list"},
54		command.ViewTemplates:    {"templates"},
55		command.ViewNetdiag:      {"netdiag/ports"},
56		command.ViewAgentUsage:   {"agent-usage/agents"},
57		command.ViewContainers:   {"containers"},
58	}
59	
60	// pendingTable is a table that still has to move to the activity column.
61	type pendingTable struct {
62		Table string
63		View  command.ViewType
64		Story string
65	}
66	
67	// pendingTables may only shrink: each migration story removes its own entries.
68	var pendingTables = []pendingTable{
69		{"oci/registry-browser", command.ViewOCIResources, "A-09a2"},
70	}
71	
72	// maxPendingTables is the ceiling: adding an exception means raising both the
73	// list and this constant in the same diff, which is visible in review. Lower it
74	// with every migration.
75	const maxPendingTables = 1
76	
77	// exemptViews have no long-running operation to show per row (inventory:
78	// "sans objet" or out of the batch), each with its reason.
79	var exemptViews = map[command.ViewType]string{
80		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
81		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
82		command.ViewGitAuth:       "a form, no table",
83		command.ViewConfiguration: "a form of settings, no table of operations",
84		command.ViewAbout:         "static facts, no table",
85		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
86		command.ViewViewer:        "a document pane, no table",
87	}
88	
89	func pendingViews() map[command.ViewType][]pendingTable {
90		out := map[command.ViewType][]pendingTable{}
91		for _, p := range pendingTables {
92			out[p.View] = append(out[p.View], p)
93		}
94		return out
95	}
96	
97	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
98		if got := len(pendingTables); got > maxPendingTables {
99			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
100		}
101		seen := map[string]bool{}
102		for _, p := range pendingTables {
103			if p.Story == "" {
104				t.Errorf("pending table %q names no story", p.Table)
105			}
106			if seen[p.Table] {
107				t.Errorf("pending table %q is listed twice", p.Table)
108			}
109			seen[p.Table] = true
110		}
111	}
112	
113	// builtView returns the view the router builds for vt, laid out at 60x30.
114	func builtView(t *testing.T, vt command.ViewType) tea.Model {
115		t.Helper()
116		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
117		a.createView(vt)
118		m := a.views[vt]
119		if m == nil {
120			t.Fatalf("view %q: the router did not build it", vt)
121		}
122		m, _ = m.Update(tea.WindowSizeMsg{Width: 60, Height: 30})
123		return m
124	}
125	
126	// classificationProblems says what is wrong with the classification of one
127	// view, empty when it is fine. It works per table: a view may be migrated for
128	// some tables and pending for others (A-09a/A-09a2/A-09b, A-10a/A-10b) as long as the
129	// two sets are disjoint; an exempt view is neither migrated nor pending.
130	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
131		var problems []string
132		mig := migrated[vt]
133		var pend []string
134		for _, p := range pending {
135			if p.View == vt {
136				pend = append(pend, p.Table)
137			}
138		}
139		_, isExempt := exempt[vt]
140		switch {
141		case len(mig) == 0 && len(pend) == 0 && !isExempt:
142			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
143		case isExempt && (len(mig) > 0 || len(pend) > 0):
144			problems = append(problems, "exempt and also migrated or pending")
145		}
146		for _, name := range pend {
147			if contains(mig, name) {
148				problems = append(problems, fmt.Sprintf("table %q is both migrated and pending", name))
149			}
150		}
151		return problems
152	}
153	
154	// staleExceptions lists the pending tables of a view that the view already
155	// reports: their exception must go.
156	func staleExceptions(vt command.ViewType, reported []string, pending []pendingTable) []string {
157		var stale []string
158		for _, p := range pending {
159			if p.View == vt && contains(reported, p.Table) {
160				stale = append(stale, p.Table)
161			}
162		}
163		return stale
164	}
165	
166	// Criterion 6: every view the router builds is migrated, pending or exempt.
167	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
168		for _, name := range command.AllViewNames() {
169			vt := command.ViewType(name)
170			t.Run(name, func(t *testing.T) {
171				for _, p := range classificationProblems(vt, migratedTables, pendingTables, exemptViews) {
172					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
173				}
174			})
175		}
176	}
177	
178	// The logic itself, on a fictitious view that is partly migrated.
179	func TestActivityGuardClassificationLogic(t *testing.T) {
180		const v command.ViewType = "fiction"
181		pending := []pendingTable{{"fiction/b", v, "A-99"}}
182		tests := []struct {
183			name     string
184			migrated map[command.ViewType][]string
185			pending  []pendingTable
186			exempt   map[command.ViewType]string
187			problems int
188			stale    []string
189			reported []string
190		}{
191			{"partly migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
192			{"unclassified fails", nil, nil, nil, 1, nil, nil},
193			{"same table both ways fails", map[command.ViewType][]string{v: {"fiction/b"}}, pending, nil, 1, []string{"fiction/b"}, []string{"fiction/b"}},
194			{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
195			{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
196		}
197		for _, tt := range tests {
198			t.Run(tt.name, func(t *testing.T) {
199				if got := classificationProblems(v, tt.migrated, tt.pending, tt.exempt); len(got) != tt.problems {
200					t.Errorf("problems = %v, want %d", got, tt.problems)
201				}
202				if got := staleExceptions(v, tt.reported, tt.pending); !equalStrings(got, tt.stale) {
203					t.Errorf("stale = %v, want %v", got, tt.stale)
204				}
205			})
206		}
207	}
208	
209	func equalStrings(a, b []string) bool {
210		if len(a) != len(b) {
211			return false
212		}
213		for i := range a {
214			if a[i] != b[i] {
215				return false
216			}
217		}
218		return true
219	}
220	
221	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
222	func TestActivityGuardMigratedViews(t *testing.T) {
223		legendTitle := indicator.Legend().Title
224		for vt, want := range migratedTables {
225			t.Run(string(vt), func(t *testing.T) {
226				m := builtView(t, vt)
227				av, ok := m.(activityView)
228				if !ok {
229					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
230				}
231				tables := av.ActivityTables()
232				for _, name := range want {
233					tb, ok := tables[name]
234					if !ok {
235						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
236						continue
237					}
238					checkColumnZero(t, vt, name, tb.Shapes())
239					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
240					if got, want := tb.RenderedWidth(), 60-2; got != want {
241						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
242					}
243				}
244				for name := range tables {
245					if !contains(want, name) {
246						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
247					}
248				}
249				// Criterion 5, help half: the legend.
250				hp, ok := m.(help.Provider)
251				if !ok {
252					t.Fatalf("view %q has no help", vt)
253				}
254				found := false
255				for _, s := range hp.GetHelpContent().Sections {
256					found = found || s.Title == legendTitle
257				}
258				if !found {
259					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
260				}
261			})
262		}
263	}
264	
265	// Criterion 6, other direction: a view that reports a table still listed as
266	// pending has migrated it; the exception must go. An exempt view must report
267	// none at all.
268	func TestActivityGuardNoStaleException(t *testing.T) {
269		for _, name := range command.AllViewNames() {
270			vt := command.ViewType(name)
271			_, isExempt := exemptViews[vt]
272			if !isExempt && len(pendingViews()[vt]) == 0 {
273				continue
274			}
275			t.Run(name, func(t *testing.T) {
276				av, ok := builtView(t, vt).(activityView)
