644					}
645				}
646			}
647		})
648		for key := range declaredGlyphConstants {
649			if !live[key] {
650				t.Errorf("declared glyph constant %q does not exist or holds no activity glyph: remove the exception", key)
651			}
652		}
653		if got := len(declaredGlyphConstants); got > 1 {
654			t.Errorf("declaredGlyphConstants has %d entries, ceiling is 1: the list may only shrink", got)
655		}
656	}
