126	// classificationProblems says what is wrong with the classification of one
127	// view, empty when it is fine. It works per table: a view may be migrated for
128	// some tables and pending for others (A-09a/A-09a2/A-09b, A-10a/A-10b) as long as the
129	// two sets are disjoint; an exempt view is neither migrated nor pending.
130	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
131		var problems []string
132		mig := migrated[vt]
133		var pend []string
134		for _, p := range pending {
135			if p.View == vt {
136				pend = append(pend, p.Table)
137			}
138		}
139		_, isExempt := exempt[vt]
140		switch {
141		case len(mig) == 0 && len(pend) == 0 && !isExempt:
142			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
143		case isExempt && (len(mig) > 0 || len(pend) > 0):
144			problems = append(problems, "exempt and also migrated or pending")
145		}
146		for _, name := range pend {
147			if contains(mig, name) {
148				problems = append(problems, fmt.Sprintf("table %q is both migrated and pending", name))
149			}
150		}
151		return problems
152	}
