126	// chainProblems says what is wrong with the declared chains, in file order:
127	// no story, or a story whose tables have all left pendingTables (the chain
128	// should have gone with the migration).
129	func chainProblems(chains map[string]rowChain, pending []pendingTable) []string {
130		var problems []string
131		files := make([]string, 0, len(chains))
132		for f := range chains {
133			files = append(files, f)
134		}
135		sort.Strings(files)
136		for _, f := range files {
137			c := chains[f]
138			if c.Story == "" || c.What == "" {
139				problems = append(problems, f+": declared row animation chain names no story or no description")
140				continue
141			}
142			still := false
143			for _, p := range pending {
144				still = still || p.Story == c.Story
145			}
146			if !still {
147				problems = append(problems, f+": declared for story "+c.Story+", which has no table left in pendingTables: remove the chain ("+c.What+")")
148			}
149		}
150		return problems
151	}
