189	func TestRowAnimationChainsOutsideTheRouterAreDeclared(t *testing.T) {
190		found := map[string]bool{}
191		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
192			if strings.HasPrefix(rel, "ui/datatable/") {
193				return
194			}
195			ast.Inspect(file, func(n ast.Node) bool {
196				hit := false
197				switch x := n.(type) {
198				case *ast.CallExpr:
199					switch f := x.Fun.(type) {
200					case *ast.SelectorExpr:
201						hit = f.Sel.Name == "AdvanceSpinner"
202					case *ast.Ident:
203						hit = f.Name == "portsSpinnerCmd"
204					}
205				case *ast.IncDecStmt:
206					hit = mentionsIdent(x.X, "tagScanSpinnerIdx")
207				case *ast.AssignStmt:
208					for _, l := range x.Lhs {
209						hit = hit || mentionsIdent(l, "tagScanSpinnerIdx")
210					}
211				}
212				if hit {
213					found[rel] = true
214					if _, ok := declaredRowChains[rel]; !ok {
215						t.Errorf("%s: a row animation chain outside the router; the router's tick animates rows (DEVDESK-139)", fset.Position(n.Pos()))
216					}
217				}
218				return true
219			})
220		})
221		var stale []string
222		for rel := range declaredRowChains {
223			if !found[rel] {
224				stale = append(stale, rel)
225			}
226		}
227		sort.Strings(stale)
228		for _, rel := range stale {
229			t.Errorf("%s is declared as a row animation chain but has none: remove the exception", rel)
230		}
231	}
