233	func mentionsIdent(e ast.Expr, name string) bool {
234		switch x := e.(type) {
235		case *ast.Ident:
236			return x.Name == name
237		case *ast.SelectorExpr:
238			return x.Sel.Name == name
239		}

	}
	return false
