1	package ociresources
2	
3	import (
4		"slices"
5	
6		tea "github.com/charmbracelet/bubbletea"
7	
8		"github.com/anthnel/devdesk/internal/command"
9		"github.com/anthnel/devdesk/internal/docker"
10		"github.com/anthnel/devdesk/internal/jobs"
11		"github.com/anthnel/devdesk/internal/ui/indicator"
12		"github.com/anthnel/devdesk/internal/ui/registryalias"
13	)
14	
15	// What is being scanned is the registry's answer, not this view's (§3.58).
16	//
17	// It held a `scanningImages` map and a `scanning` bool derived from it, and both
18	// knew only what this view had launched. An image scanned from `:sec` — the same
19	// image, the same cache entry — went unnoticed here, so `S` offered itself on a
20	// row already being scanned and the two wrote the same file.
21	//
22	// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
23	// — the image list, the networks, a `docker` action on a row — and a load is not
24	// a job. What moved is the blink phase of the activity column, which comes from
25	// the one chain the router holds (D5).
26	
27	// handleJobsChanged takes the router's snapshot. It is the only writer of the
28	// two fields.
29	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
30		m.jobs = msg.Runs
31		m.failures = slices.Clone(msg.Failures)
32		m.contextName = msg.Context
33		// The footer's spinner is deliberately not touched: here it belongs to
