11	
12	// rebuildTagTable re-decorates the rows and hands them to the table.
13	//
14	// The decoration — the scan counts, whether a scan is running, the registry's
15	// label — is not on the tag, and the columns are built once so they cannot
16	// reach the browser for it. So it is recomputed wholesale on every change,
17	// exactly as the images tab does with imageRow.
18	//
19	// The filters are applied here because they narrow the tags before the table
20	// sees them; the sort and the header arrows are the table's.
21	func (b *RegistryBrowser) rebuildTagTable() {
22		tags := b.filteredMultiTags()
23		frame := spinner.Dot.Frames[b.tagScanSpinnerIdx%len(spinner.Dot.Frames)]
24	
25		rows := make([]tagRow, len(tags))
26		for i, t := range tags {
27			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
28			label := t.Alias
29			if label == "" {
30				label = t.RegistryURL
31			}
32			entry, scanned := b.scanCache[imageName]
33			rows[i] = tagRow{
34				tag:      t,
35				label:    label,
36				entry:    entry,
37				scanned:  scanned,
38				scanning: b.scanningTags[imageName],
39				frame:    frame,
40			}
41		}
42	
43		b.tagTable.SetItems(rows)
44		b.resizeTagTable()
45	}
46	
47	// View renders the browser for the current state.
48	func (b *RegistryBrowser) View() string {
49		switch b.state {
50		case browserStateTags:
51			return b.viewTags()
52		default:
53			return b.viewInput()
54		}
55	}
56	
57	func (b *RegistryBrowser) viewInput() string {
58		var sb strings.Builder
59	
60		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
61		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
62		sb.WriteString("\n\n")
63	
64		if len(b.rows) > 0 {
65			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
66			for i, row := range b.rows {
67				focused := b.focusedField == b.brFieldReg(i)
68				if row.groupSlug != "" {
69					// One checkbox for the whole group, with a third state for a
70					// partial selection — eight proxies are not eight keystrokes.
71					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
72				} else {
73					sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
74				}
75				if i < len(b.rows)-1 {
76					sb.WriteString("\n")
77				}
78			}
79			sb.WriteString("\n\n")
80		}
81	
82		sb.WriteString("  ")
83		sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))
84	
85		return sb.String()
86	}
87	
88	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
89		var labelStr string
90		if b.focusedField == fieldIdx {
91			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
92		} else {
93			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
94		}
95		return labelStr + "\n  " + value
96	}
97	
98	// viewTags renders the tag table. The search says so in the footer, with a
99	// spinner (LoadingLabel), and an empty table stays a table (Rule 139) — the
100	// count lives in GetHeaderInfo's "Tags" field.
101	func (b *RegistryBrowser) viewTags() string {
102		return b.tagTable.View()
103	}
104	
105	// LoadingLabel names what the browser is fetching, for the OCI view's footer.
106	// The second result is false when nothing is in flight.
107	func (b *RegistryBrowser) LoadingLabel() (string, bool) {
108		if b.state == browserStateTags && b.pendingSearches > 0 {
109			return "Searching registries...", true
110		}
111		return "", false
112	}
113	
114	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
115	func (b *RegistryBrowser) FilterIsVisible() bool {
116		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
117	}
118	
119	// FilterBarView renders the filter bar (2 lines) for display in the footer.
120	func (b *RegistryBrowser) FilterBarView(width int) string {
121		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
122	
123		var left string
124		if b.filterActive {
125			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
126		} else if b.filterInput.Value() != "" {
127			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
128		} else {
129			left = theme.DimStyle.Render("/ filter…")
130		}
131	
132		if !b.registryFilter.isEmpty() {
133			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
134		}
135	
136		inner := theme.Bg(" ") + left
137		paddedInner := theme.PadWithBg(inner, width-2)
138		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
139		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
140		return contentLine + "\n" + bottomBorder
141	}
