12		"github.com/anthnel/devdesk/internal/ui/registryalias"
13	)
14	
15	// What is being scanned is the registry's answer, not this view's (§3.58).
16	//
17	// It held a `scanningImages` map and a `scanning` bool derived from it, and both
18	// knew only what this view had launched. An image scanned from `:sec` — the same
19	// image, the same cache entry — went unnoticed here, so `S` offered itself on a
20	// row already being scanned and the two wrote the same file.
21	//
22	// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
23	// — the image list, the networks, a `docker` action on a row — and a load is not
24	// a job. What moved is the blink phase of the activity column, which comes from
25	// the one chain the router holds (D5).
26	
27	// handleJobsChanged takes the router's snapshot. It is the only writer of the
28	// two fields.
29	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
30		m.jobs = msg.Runs
31		m.failures = slices.Clone(msg.Failures)
32		m.contextName = msg.Context
33		// The footer's spinner is deliberately not touched: here it belongs to
34		// *loading* — a tab reading its list — and this view's scan progress is on
35		// the rows, not in the footer. Two writers of one field would fight every
36		// frame a scan and a load overlapped.
37		m.updateImageTable()
38		if m.registryBrowser != nil {
39			m.registryBrowser.SetTagScanningSet(m.scanningNames())
40		}
41		return m, nil
42	}
43	
44	// handleFrameMsg takes the blink phase of the activity column. Nothing is
45	// rebuilt: the table reads the phase at render. The footer frame is the
46	// router's only while no tab load is running: the view's own spinner owns it
47	// then, and two writers would fight every frame.
48	func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
49		m.imageTable.SetBlinkPhase(msg.Blink)
50		m.networkTable.SetBlinkPhase(msg.Blink)
51		m.volumeTable.SetBlinkPhase(msg.Blink)
52		m.registryTable.SetBlinkPhase(msg.Blink)
53		if !m.loading && !m.loadingNets && !m.loadingVols && !m.loadingRegs {
54			m.footer.SetSpinnerFrame(msg.RenderedFrame)
55		}
56		return m, nil
57	}
58	
59	// WantsBlink reports whether an Images row is in an animated state (running,
60	// or an action observed on it). A queued row and a remembered failure are
61	// steady. It is the level the router's BlinkingView check reads.
62	func (m Model) WantsBlink() bool {
63		for _, r := range m.imageTable.Items() {
64			if r.Activity.State == indicator.Running {
65				return true
66			}
67		}
68		// A busy row (network, volume, registry) and a group being discovered both
69		// show a blinking dot.
70		return len(m.refreshingGroups) > 0 ||
71			len(m.networkTable.BusyLabels()) > 0 ||
72			len(m.volumeTable.BusyLabels()) > 0 ||
73			len(m.registryTable.BusyLabels()) > 0
74	}
75	
76	// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
77	func (m Model) scanRun(names []string) jobs.Run {
78		run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
79		// The alias is applied here rather than by whoever shows the run: it is
80		// this view's configuration that defines it, and `:jobs` has no business
81		// reading a registry list to print a name.
82		aliases := registryalias.From(m.registries)
83		for _, name := range names {
84			if display := docker.ApplyAliases(name, aliases); display != name {
85				run = run.WithDisplay(name, display)
86			}
87		}
88		return run
89	}
90	
91	// scanningImage reports whether an image is queued or being scanned, whoever
92	// started it.
93	func (m Model) scanningImage(name string) bool {
94		for _, run := range jobs.Unfinished(m.jobs) {
95			if run.Kind != jobs.KindScan {
96				continue
97			}
98			for _, item := range run.Items {
99				if item.Target == name && !item.State.Terminal() {
100					return true
101				}
102			}
103		}
104		return false
105	}
106	
107	// scanningNames lists every image with a scan in flight, for the registry
108	// browser, which decorates its tag rows from the same source.
109	func (m Model) scanningNames() map[string]bool {
110		out := make(map[string]bool)
111		for _, run := range jobs.Unfinished(m.jobs) {
112			if run.Kind != jobs.KindScan {
113				continue
114			}
115			for _, item := range run.Items {
116				if !item.State.Terminal() {
117					out[item.Target] = true
118				}
119			}
120		}
121		return out
122	}
123	
124	// anyScanRunning reports whether a scan is going anywhere. It is what A and
125	// ctrl+a refuse on, and it is true for a scan this view did not start — which
126	// is the point: the two would write the same cache entries.
127	func (m Model) anyScanRunning() bool { return len(m.scanningNames()) > 0 }
128	
129	// pullRun builds the run behind a registry-browser pull.
130	func (m Model) pullRun(name string) jobs.Run {
131		run := jobs.NewRun(jobs.KindPull, command.ViewOCIResources, "", "images", name)
132		aliases := registryalias.From(m.registries)
133		if display := docker.ApplyAliases(name, aliases); display != name {
134			run = run.WithDisplay(name, display)
135		}
136		return run
137	}
138	
139	// pullingImage reports whether a pull for name is queued or running.
140	func (m Model) pullingImage(name string) bool {
141		for _, run := range jobs.Unfinished(m.jobs) {
142			if run.Kind != jobs.KindPull {
143				continue
144			}
145			for _, item := range run.Items {
146				if item.Target == name && !item.State.Terminal() {
147					return true
148				}
149			}
150		}
151		return false
152	}
153	
154	// pullingNames lists every image with a pull in flight, for imageRows —
155	// which is what shows a placeholder row for an image not pulled before.
156	func (m Model) pullingNames() map[string]bool {
157		out := make(map[string]bool)
158		for _, run := range jobs.Unfinished(m.jobs) {
159			if run.Kind != jobs.KindPull {
160				continue
161			}
162			for _, item := range run.Items {
163				if !item.State.Terminal() {
164					out[item.Target] = true
165				}
166			}
167		}
168		return out
169	}
170	
171	// ── What each message tells the registry (jobs.Reporter) ─────────────────────
172	
173	func (m ImageScanStartingMsg) Transition() jobs.Transition {
174		return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
175	}
176	
177	func (m ImageScanFinishedMsg) Transition() jobs.Transition {
178		t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
179		if m.Err != nil {
180			t.State = jobs.ItemFailed
181			t.Detail = "scan failed — check logs"
182		}
183		return t
184	}
185	
186	func (m RegistryPullStartingMsg) Transition() jobs.Transition {
187		return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
188	}
189	
190	func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
191		t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
192		switch {
193		case len(m.InUse) > 0:
194			t.State = jobs.ItemFailed
195			t.Detail = "not updated — the image is in use"
196		case isBlocked(m.Err):
197			// The reason, not "check logs": it names the rule, and it is what an
198			// agent that asked for the pull reads (§3.82).
199			t.State = jobs.ItemFailed
200			t.Detail = "refused — " + m.Err.Error()
201		case m.Err != nil:
202			t.State = jobs.ItemFailed
203			t.Detail = "pull failed — check logs"
204		}
205		return t
206	}
207	
208	// Compile-time proof that every progress message can be applied. One added
209	// without a transition would leave its row spinning for the life of the view.
210	var (
211		_ jobs.Reporter = ImageScanStartingMsg{}
212		_ jobs.Reporter = ImageScanFinishedMsg{}
213		_ jobs.Reporter = RegistryPullStartingMsg{}
214		_ jobs.Reporter = RegistryPullCompleteMsg{}
215	)
