10	// ociKinds are the operations whose activity or remembered failure an Images
11	// row shows: a scan or a pull, whoever started it (D5).
12	var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}
13	
14	// rowActivity resolves what one Images row says about its activity, read from
15	// the router snapshot against the context it carries. The identity is the raw
16	// reference, never a canonical form. A removal in flight is this view's own
17	// observation: it is reported as Running with its label.
18	func (m Model) rowActivity(r imageRow) components.RowActivity {
19		q := components.RowQuery{
20			Runs: m.jobs, Failures: m.failures, Context: m.contextName,
21			Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
22		}
23		if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
24			q.Observed = indicator.Running
25			q.ObservedText = label
26		}
27		return components.DescribeRow(q)
28	}
29	
30	// scanRunning reports whether a scan of the image is running now in the
31	// current context. A queued scan is not running.
32	func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }
33	
34	// pullRunning reports whether a pull of the image is running now in the
35	// current context. A queued pull is not running.
36	func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }
37	
38	func (m Model) runningOn(name string, kind jobs.Kind) bool {
39		for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
40			if a.Item.State == jobs.ItemRunning {
41				return true
42			}
43		}
44		return false
45	}
46	
47	// ActivityTables returns the read-only face of the view's table, keyed by the
48	// name the activity-column guard (internal/app) knows it by. Tests only.
49	func (m Model) ActivityTables() map[string]datatable.ActivityTable {
50		return map[string]datatable.ActivityTable{
51			"oci/images":     &m.imageTable,
52			"oci/networks":   &m.networkTable,
53			"oci/volumes":    &m.volumeTable,
54			"oci/registries": &m.registryTable,
55		}
56	}
